select e.emp_id, e.emp_no, e.emp_name, d.dept_name, p.pos_name, e.emp_email, e.emp_mobile, e.emp_status, to_char(e.hire_date, 'YYYY-MM-DD') as hire_date from employee e join emp_position p on e.pos_id = p.pos_id join department d on e.dept_id = d.dept_id
e.com_id = #{comId}
and e.dept_id = #{deptId}
and e.pos_id = #{posId}
and e.emp_status = #{empStatus}
and (e.emp_name like '%' || #{keyword} || '%' or e.emp_no like '%' || #{keyword} || '%')
order by p.pos_order, e.emp_no offset #{pstartno} rows fetch next #{onepagelist} rows only

select count(*)
from employee e
join emp_position p on e.pos_id = p.pos_id
join department   d on e.dept_id = d.dept_id

	e.com_id = #{comId}

		and e.dept_id = #{deptId}


