		and (e.emp_name like '%' || #{keyword} || '%'
		  or e.emp_no   like '%' || #{keyword} || '%')

select *
from employee
where emp_no = #{empNo}
  and emp_email = #{empEmail} 
  and emp_mobile = #{empMobile}

